<script setup lang="ts">
import {ref,watch,nextTick,onBeforeUnmount} from 'vue';
import * as XLSX from 'xlsx';
import ToolButton from '@/components/ui/ToolButton.vue';
import Icon from '@/components/ui/ToolbarIcon.vue';
import PopupTransition from '@/components/ui/PopupTransition.vue';
import type {useEditor} from '../composables/useEditor';
import type {useGridInteraction} from '../composables/useGridInteraction';
import type {ExcelRegionClipboard} from '@shared/excelEditing';
const props=defineProps<{editor:ReturnType<typeof useEditor>;grid:ReturnType<typeof useGridInteraction>;fileId:string;autoSize:(axis:'row'|'column',start:number,end:number)=>Promise<boolean>;rowSize:(r:number)=>number;colSize:(c:number)=>number}>();
const panel=ref<'layout'|'fill'|null>(null),menu=ref<{kind:'merge'|'fill'|'paste';x:number;y:number}|null>(null),axis=ref<'row'|'column'>('row'),start=ref('1'),end=ref('1'),size=ref(18),operation=ref('size');
const fillRange=ref(''),fillDirection=ref<'row'|'column'>('row'),fillSeries=ref(false);let seed:XLSX.Range;
const brush=ref<ExcelRegionClipboard>();
function prepare(){return props.grid.commit()&&props.editor.finishCell();}
function close(){panel.value=null;menu.value=null;}
function openMenu(kind:'merge'|'fill'|'paste',event:MouseEvent){if(!prepare())return;props.grid.closeAll();const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();menu.value={kind,x:Math.max(4,Math.min(rect.left,innerWidth-230)),y:Math.max(4,Math.min(rect.bottom+4,innerHeight-260))};void nextTick(()=>{const root=document.querySelector(`[data-file-id="${props.fileId}"] .excel-grid-menu`);root?.querySelectorAll<HTMLButtonElement>('button').forEach(button=>{button.setAttribute('role','menuitem');button.title=button.textContent?.trim()||'';});root?.querySelector<HTMLElement>('button')?.focus();});}
function menuKey(event:KeyboardEvent){if(!['ArrowDown','ArrowUp','Home','End'].includes(event.key))return;event.preventDefault();const buttons=Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('button')),current=buttons.indexOf(document.activeElement as HTMLButtonElement),index=event.key==='Home'?0:event.key==='End'?buttons.length-1:(current+(event.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[index]?.focus();}
function setAxis(){const range=props.grid.range.value;start.value=axis.value==='row'?String(range.s.r+1):XLSX.utils.encode_col(range.s.c);end.value=axis.value==='row'?String(range.e.r+1):XLSX.utils.encode_col(range.e.c);size.value=axis.value==='row'?props.rowSize(range.s.r):props.colSize(range.s.c);}
function openLayout(){if(!prepare())return;props.grid.closeAll();axis.value=props.editor.selection.value.mode==='columns'?'column':'row';setAxis();operation.value='size';panel.value='layout';menu.value=null;}
function index(value:string){if(axis.value==='row'){if(!/^\d+$/.test(value.trim()))throw Error('行号需为正整数。');return Number(value)-1;}if(!/^[a-z]+$/i.test(value.trim()))throw Error('请输入列标，例如 A 或 BC。');return XLSX.utils.decode_col(value.trim().toUpperCase());}
async function applyLayout(){try{const op={axis:axis.value,start:index(start.value),end:index(end.value)};const result=operation.value==='auto'?await props.autoSize(op.axis,op.start,op.end):await props.editor.layout({...op,...(operation.value==='size'?{size:size.value}:operation.value==='showAll'?{unhideAll:true}:{hidden:operation.value==='hide'})});if(result)close();}catch(e){props.editor.error.value=(e as Error).message;}}
async function merge(unmerge=false,center=false){close();if(prepare())await props.editor.merge(props.grid.range.value,unmerge,center);}
async function fill(direction:'row'|'column',series=false){close();if(!prepare())return;const target=JSON.parse(JSON.stringify(props.grid.range.value)) as XLSX.Range,source={s:{...target.s},e:{...target.e}};if(direction==='row')source.e.r=Math.min(target.e.r,source.s.r+(series?1:0));else source.e.c=Math.min(target.e.c,source.s.c+(series?1:0));await props.editor.fill(source,target,direction,series);}
function openFill(){if(!prepare())return;close();seed=JSON.parse(JSON.stringify(props.grid.range.value));fillRange.value=XLSX.utils.encode_range({s:seed.s,e:{r:seed.e.r+10,c:seed.e.c}});fillDirection.value='row';fillSeries.value=false;panel.value='fill';}
async function applyFill(){try{if(!/^[A-Z]+\d+(?::[A-Z]+\d+)?$/i.test(fillRange.value.trim()))throw Error('请输入连续填充区域，例如 A1:A20。');const target=XLSX.utils.decode_range(fillRange.value.trim().toUpperCase());if(target.s.r!==seed.s.r||target.s.c!==seed.s.c||target.e.r<seed.e.r||target.e.c<seed.e.c||(fillDirection.value==='row'?target.e.c!==seed.e.c:target.e.r!==seed.e.r))throw Error('填充区域须从原选区开始，沿所选方向延伸。');if(fillSeries.value&&(fillDirection.value==='row'?seed.e.r-seed.s.r:seed.e.c-seed.s.c)>1)throw Error('序列填充请先选择一格或两格种子。');if(await props.editor.fill(seed,target,fillDirection.value,fillSeries.value))close();}catch(e){props.editor.error.value=(e as Error).message;}}
async function paint(){if(brush.value){brush.value=undefined;return;}if(!prepare())return;brush.value=await props.editor.capture(props.grid.range.value);}
async function paintTarget(event:PointerEvent){const target=event.target as Element;if(!brush.value||!target.closest(`[data-file-id="${props.fileId}"] .spreadsheet td`))return;await nextTick();const clip=brush.value;brush.value=undefined;const chosen=props.grid.range.value,h=clip.range.e.r-clip.range.s.r+1,w=clip.range.e.c-clip.range.s.c+1;const range=(chosen.e.r-chosen.s.r+1)%h===0&&(chosen.e.c-chosen.s.c+1)%w===0?chosen:{s:chosen.s,e:{r:chosen.s.r+h-1,c:chosen.s.c+w-1}};await props.editor.pasteRich(clip,range,'formats');}
function outside(event:PointerEvent){const target=event.target as Element;if(!target.closest('.excel-grid-menu,.excel-grid-command'))menu.value=null;}
function key(event:KeyboardEvent){if(!document.querySelector<HTMLElement>(`[data-file-id="${props.fileId}"]`)?.clientWidth)return;if(event.key==='Escape'){if(props.editor.confirmation.value){props.editor.answerRange(false);event.preventDefault();return;}if(menu.value||panel.value||brush.value){close();brush.value=undefined;event.preventDefault();}}}
window.addEventListener('pointerdown',outside);window.addEventListener('pointerup',paintTarget);window.addEventListener('keydown',key);
onBeforeUnmount(()=>{window.removeEventListener('pointerdown',outside);window.removeEventListener('pointerup',paintTarget);window.removeEventListener('keydown',key);props.editor.answerRange(false);});
watch(()=>props.editor.confirmation.value,()=>{void nextTick(()=>document.querySelector<HTMLElement>(`[data-file-id="${props.fileId}"] .excel-range-confirm-cancel`)?.focus());});
function trap(event:KeyboardEvent){const fields=Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('input,select,button:not(:disabled)'));const first=fields[0],last=fields.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
defineExpose({openPaste:(event:MouseEvent)=>openMenu('paste',event),paint,brush,openLayout});
</script>
<template>
  <span class="excel-command-group" data-group="layout"><ToolButton class="excel-grid-command excel-layout-toggle" icon="layout" title="行高、列宽及隐藏行列" :disabled="editor.saving.value" @click="openLayout"/><ToolButton class="excel-grid-command excel-merge-toggle" icon="merge" title="合并或取消合并单元格" :disabled="editor.saving.value" @click="openMenu('merge',$event)"/><ToolButton class="excel-grid-command excel-fill-toggle" icon="fill" title="填充选区或序列" :disabled="editor.saving.value" @click="openMenu('fill',$event)"/></span>
  <div v-if="menu" class="excel-grid-menu" role="menu" :style="{left:menu.x+'px',top:menu.y+'px'}" @keydown="menuKey">
    <template v-if="menu.kind==='merge'"><button type="button" data-grid-action="merge" @click="merge()">合并单元格</button><button type="button" data-grid-action="merge-center" @click="merge(false,true)">合并并居中</button><button type="button" data-grid-action="unmerge" @click="merge(true)">取消合并</button></template>
    <template v-else-if="menu.kind==='paste'"><button v-for="mode in [{value:'all',label:'常规粘贴：内容、公式、格式'},{value:'values',label:'只粘贴值'},{value:'formulas',label:'只粘贴内容和公式'},{value:'formats',label:'只粘贴格式'}] as const" type="button" :data-paste-mode="mode.value" @click="close();grid.paste(mode.value)">{{mode.label}}</button></template>
    <template v-else><button type="button" data-grid-action="fill-down" @click="fill('row')">向下复制填充</button><button type="button" data-grid-action="fill-right" @click="fill('column')">向右复制填充</button><button type="button" data-grid-action="series-down" @click="fill('row',true)">向下序列填充</button><button type="button" data-grid-action="series-right" @click="fill('column',true)">向右序列填充</button><button type="button" data-grid-action="fill-custom" @click="openFill">自定义填充区域…</button></template>
  </div>
  <PopupTransition><div v-if="panel" class="excel-grid-overlay" @pointerdown.self="close"><form class="excel-grid-dialog" role="dialog" aria-modal="true" :aria-label="panel==='layout'?'行列布局':'区域填充'" @keydown.tab="trap" @submit.prevent="panel==='layout'?applyLayout():applyFill()">
    <strong>{{panel==='layout'?'行列布局':'填充区域'}}</strong>
    <template v-if="panel==='layout'"><label>类型<select v-model="axis" aria-label="布局类型" :disabled="editor.saving.value" @change="setAxis"><option value="row">行</option><option value="column">列</option></select></label><label>起始{{axis==='row'?'行号':'列标'}}<input v-model="start" aria-label="布局起始" :disabled="editor.saving.value" required/></label><label>结束{{axis==='row'?'行号':'列标'}}<input v-model="end" aria-label="布局结束" :disabled="editor.saving.value" required/></label><label>操作<select v-model="operation" aria-label="布局操作" :disabled="editor.saving.value"><option value="size">设置{{axis==='row'?'行高':'列宽'}}</option><option value="auto">自动适应内容</option><option value="hide">隐藏所选{{axis==='row'?'行':'列'}}</option><option value="show">取消隐藏所选{{axis==='row'?'行':'列'}}</option><option value="showAll">取消隐藏全部{{axis==='row'?'行':'列'}}</option></select></label><label v-if="operation==='size'">{{axis==='row'?'行高（磅）':'列宽（字符）'}}<input v-model.number="size" type="number" min="1" :max="axis==='row'?409:255" step="0.1" aria-label="布局尺寸" :disabled="editor.saving.value" required/></label><small>编辑尺寸会保存到副本；隐藏后可在此输入范围恢复，或取消隐藏全部。</small></template>
    <template v-else><label>目标区域<input v-model="fillRange" aria-label="填充区域" :disabled="editor.saving.value" required/></label><label>方向<select v-model="fillDirection" aria-label="填充方向" :disabled="editor.saving.value"><option value="row">向下</option><option value="column">向右</option></select></label><label><input v-model="fillSeries" type="checkbox" :disabled="editor.saving.value"/>数字／日期序列（文本重复）</label><small>复制填充调整公式的相对引用；序列用一格的步长 1 或两格差值。</small></template>
    <p v-if="editor.error.value" class="excel-edit-error" role="alert">{{editor.error.value}}</p><div class="excel-dialog-actions"><button type="button" :disabled="editor.saving.value" @click="close">取消</button><button type="submit" :disabled="editor.saving.value">应用</button></div>
  </form></div></PopupTransition>
  <PopupTransition><div v-if="editor.confirmation.value" class="excel-grid-overlay" @pointerdown.self="editor.answerRange(false)"><form class="excel-grid-dialog" role="dialog" aria-modal="true" :aria-label="editor.confirmation.value.kind==='merge'?'合并内容确认':'覆盖内容确认'" @keydown.tab="trap" @submit.prevent="editor.answerRange(editor.confirmation.value.selected)"><strong>{{editor.confirmation.value.kind==='merge'?'合并会清空其他单元格内容':'目标区域已有内容'}}</strong><p>共 {{editor.confirmation.value.count}} 格；{{editor.confirmation.value.kind==='merge'?'请选择需要保留的内容，其余将清空。':'继续将覆盖这些内容，操作可整体撤销。'}}</p><label v-if="editor.confirmation.value.kind==='merge'">保留单元格<select v-model="editor.confirmation.value.selected" aria-label="合并保留内容"><option v-for="cell in editor.confirmation.value.cells" :key="cell.address" :value="cell.address">{{cell.address}}：{{cell.text}}</option></select></label><ul class="excel-conflict-list"><li v-for="cell in editor.confirmation.value.cells" :key="cell.address">{{cell.address}}：{{cell.text}}</li></ul><small v-if="editor.confirmation.value.count>200">仅显示前 200 格，请缩小范围以检查其他内容。</small><div class="excel-dialog-actions"><button type="button" class="excel-range-confirm-cancel" @click="editor.answerRange(false)">取消</button><button type="submit" class="excel-range-confirm-accept">{{editor.confirmation.value.kind==='merge'?'保留所选内容并合并':'确认覆盖'}}</button></div></form></div></PopupTransition>
</template>
